                    projectRoleId?: string | null;
                    /** @description The project task ID (`uuid`) of the project task for the allocation. */
                    projectTaskId?: string | null;
                    /** @description The time off type ID (`uuid`) of the time off type for the allocation. Must be provided if the `assignmentTypeId` is `time_off`. */
